private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.size() < 2) {
        return true; // A graph with 0 or 1 vertex is trivially a clique
    }

    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !graph.hasEdgeConnecting(vertex1, vertex2)) {
                return false; // Found a pair of vertices not connected by an edge
            }
        }
    }

    return true; // All pairs of vertices are connected by an edge
}

boolean innerIsClique = true;
Set<V> checkedVertices = new HashSet<>();

for (V vertex : vertices) {
    if (checkedVertices.contains(vertex)) {
        continue;
    }
    checkedVertices.add(vertex);
    Set<V> neighbors = graph.getNeighbors(vertex);
    if (neighbors.size() != vertices.size() - 1) {
        innerIsClique = false;
        break;
    }
    for (V neighbor : neighbors) {
        if (!vertices.contains(neighbor)) {
            return false;
        }
    }
}

return innerIsClique;

