public static void createConfigurationDirectory() {
    String userHome = System.getProperty("user.home");
    File lf5Dir;

    if (System.getProperty("os.name").startsWith("Windows 2000")) {
        lf5Dir = new File(userHome, "Documents and Settings/lf5");
    } else {
        lf5Dir = new File(userHome, "lf5");
    }

    if (!lf5Dir.exists()) {
        try {
            if (lf5Dir.mkdirs()) {
                System.out.println("Configuration directory created: " + lf5Dir.getAbsolutePath());
