public long readRawVarint64() throws IOException {
    long result = 0;
    for (int shift = 0; shift < 64; shift += 7) {
        int b = input.readByte();
        result |= ((long)(b & 0x7F)) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("Varint too long");
}

public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    while (true) {
        byte b = readByte();
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Varint format error");
        }
    }
    return result;
}

public long readRawVarint64() throws IOException {
    int b = read();
    if (b >= 0) {
        return b;
    }
    long result = b & 0x7F;
    for (int shift = 7; shift < 64; shift += 7) {
        b = read();
        result |= (long) (b & 0x7F) << shift;
        if (b >= 0) {
            break;
        }
    }
    return result;
}

try {
    long result = 0;
    int shift = 0;
    int b;
    while (((b = inputStream.read()) & 0x80) == 0x80) {
        result |= ((long) (b & 0x7F)) << shift;
        shift += 7;
    }
    result |= ((long) (b & 0x7F)) << shift;
    return result;
} catch (IOException e) {
    throw new IOException("Failed to read Raw Varint", e);
}

private long readRawVarint64(InputStream stream) throws IOException {
    long result = 0;
    for (int shift = 0; shift < 64; shift += 7) {
        int b = stream.read();
        if (b == -1) {
            throw new EOFException("Unexpected EOF while reading varint");
        }
        result |= ((long) (b & 0x7F)) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("Varint is too long (more than 10 bytes)");
}

